// Open Design on Azure Container Instances (ACI) — evaluation deployment.
//
// Single serverless container group with a public FQDN. State lives on the
// container's local disk, which is EPHEMERAL — it is reset whenever the group
// is restarted or recreated. This lane is for evaluation and demos.
//
// Why no persistent volume: Open Design stores SQLite under OD_DATA_DIR, and
// SQLite needs real file locking. ACI's only persistent volume type is Azure
// Files (SMB), where SQLite WAL/locking is unsupported and corrupts. So we
// keep the data dir on the container's local filesystem.
//
// SECURITY: ACI exposes the port over plain HTTP (no managed TLS). Access is
// gated by OD_API_TOKEN and browser traffic by OD_ALLOWED_ORIGINS. For
// internet-facing HTTPS use app-service.bicep.

@description('Base name for the deployment. A globally-unique suffix is appended to the DNS label.')
param name string = 'open-design'

@description('Azure region. Defaults to the resource group location.')
param location string = resourceGroup().location

@description('Container image to run. Pin to a digest (image@sha256:...) for production.')
param image string = 'docker.io/vanjayak/open-design:latest'

@secure()
@minLength(32)
@description('Required API token guarding the daemon. Generate one with: openssl rand -hex 32')
param apiToken string

@description('vCPU cores allocated to the container.')
param cpuCores int = 1

@description('Memory (GiB) allocated to the container. Raise for large exports or concurrent agent runs.')
param memoryInGb string = '1.5'

@description('Node.js heap cap passed to the container via NODE_OPTIONS.')
param nodeOptions string = '--max-old-space-size=192'

@description('Extra browser origins allowed to call /api, comma-separated. The container FQDN is always allowed.')
param extraAllowedOrigins string = ''

// Runtime invariants of the image, not user-facing knobs.
var containerPort = 7456
var dataDir = '/app/.od'

// ACI exposes the port verbatim (no 80 -> 7456 mapping), so the base URL
// carries the container port.
var dnsNameLabel = '${name}-${uniqueString(resourceGroup().id)}'
var fqdn = '${dnsNameLabel}.${toLower(location)}.azurecontainer.io'
var publicBaseUrl = 'http://${fqdn}:${containerPort}'
var allowedOrigins = empty(extraAllowedOrigins) ? publicBaseUrl : '${publicBaseUrl},${extraAllowedOrigins}'

resource containerGroup 'Microsoft.ContainerInstance/containerGroups@2023-05-01' = {
  name: '${name}-aci'
  location: location
  properties: {
    osType: 'Linux'
    restartPolicy: 'Always'
    ipAddress: {
      type: 'Public'
      dnsNameLabel: dnsNameLabel
      ports: [
        {
          protocol: 'TCP'
          port: containerPort
        }
      ]
    }
    containers: [
      {
        name: 'open-design'
        properties: {
          image: image
          ports: [
            {
              protocol: 'TCP'
              port: containerPort
            }
          ]
          resources: {
            requests: {
              cpu: cpuCores
              memoryInGB: json(memoryInGb)
            }
          }
          environmentVariables: [
            {
              name: 'OD_BIND_HOST'
              value: '0.0.0.0'
            }
            {
              name: 'OD_PORT'
              value: '${containerPort}'
            }
            {
              name: 'OD_WEB_PORT'
              value: '${containerPort}'
            }
            {
              name: 'OD_DATA_DIR'
              value: dataDir
            }
            {
              name: 'OD_PUBLIC_BASE_URL'
              value: publicBaseUrl
            }
            {
              name: 'OD_ALLOWED_ORIGINS'
              value: allowedOrigins
            }
            {
              name: 'NODE_ENV'
              value: 'production'
            }
            {
              name: 'NODE_OPTIONS'
              value: nodeOptions
            }
            {
              name: 'OD_API_TOKEN'
              secureValue: apiToken
            }
          ]
          livenessProbe: {
            httpGet: {
              path: '/api/health'
              port: containerPort
              scheme: 'HTTP'
            }
            initialDelaySeconds: 20
            periodSeconds: 30
            failureThreshold: 3
          }
        }
      }
    ]
  }
}

@description('Public URL of the deployed container (plain HTTP, port included).')
output appUrl string = publicBaseUrl

@description('Health endpoint to poll after deployment.')
output healthUrl string = '${publicBaseUrl}/api/health'

@description('Fully-qualified domain name assigned to the container group.')
output fqdn string = fqdn

// Open Design on Azure App Service for Containers (evaluation deployment).
//
// Single-instance Linux web app behind Azure's managed HTTPS. State lives on
// the container's local disk, which is EPHEMERAL — it is reset on restart,
// redeploy, or scale. This lane is for evaluation and demos, not durable data.
//
// Why no persistent volume: Open Design stores SQLite under OD_DATA_DIR, and
// SQLite needs real file locking. App Service's persistent storage is backed
// by Azure Files (SMB), where SQLite WAL/locking is unsupported and corrupts.
// So we deliberately keep the data dir on the container's local filesystem.

@description('Base name for the deployment. A globally-unique suffix is appended to the web app.')
param name string = 'open-design'

@description('Azure region. Defaults to the resource group location.')
param location string = resourceGroup().location

@description('Container image to run. Pin to a digest (image@sha256:...) for production.')
param image string = 'docker.io/vanjayak/open-design:latest'

@description('App Service plan SKU. B1 is the smallest tier that supports Always On and health checks.')
param appServicePlanSku string = 'B1'

@secure()
@minLength(32)
@description('Required API token guarding the daemon. Generate one with: openssl rand -hex 32')
param apiToken string

@description('Node.js heap cap passed to the container via NODE_OPTIONS.')
param nodeOptions string = '--max-old-space-size=192'

@description('Extra browser origins allowed to call /api, comma-separated. The App Service default hostname is always allowed.')
param extraAllowedOrigins string = ''

// Runtime invariants of the image, not user-facing knobs.
var containerPort = 7456
var dataDir = '/app/.od'

// Default App Service hostname is deterministic, so we derive the public URL up
// front and avoid a circular reference on the site's own appSettings.
var webAppName = '${name}-${uniqueString(resourceGroup().id)}'
var publicBaseUrl = 'https://${webAppName}.azurewebsites.net'
var allowedOrigins = empty(extraAllowedOrigins) ? publicBaseUrl : '${publicBaseUrl},${extraAllowedOrigins}'

resource plan 'Microsoft.Web/serverfarms@2023-12-01' = {
  name: '${name}-plan'
  location: location
  kind: 'linux'
  sku: {
    name: appServicePlanSku
    capacity: 1
  }
  properties: {
    reserved: true // required for Linux plans
  }
}

resource webApp 'Microsoft.Web/sites@2023-12-01' = {
  name: webAppName
  location: location
  kind: 'app,linux,container'
  properties: {
    serverFarmId: plan.id
    httpsOnly: true
    siteConfig: {
      linuxFxVersion: 'DOCKER|${image}'
      alwaysOn: true
      ftpsState: 'Disabled'
      minTlsVersion: '1.2'
      http20Enabled: true
      healthCheckPath: '/api/health'
      numberOfWorkers: 1 // SQLite is single-writer: keep one worker.
      appSettings: [
        {
          name: 'WEBSITES_PORT' // route inbound traffic to the container port
          value: '${containerPort}'
        }
        {
          // Keep the data dir on the container's local disk (real file
          // locking). Azure Files-backed storage corrupts SQLite.
          name: 'WEBSITES_ENABLE_APP_SERVICE_STORAGE'
          value: 'false'
        }
        {
          name: 'WEBSITES_CONTAINER_START_TIME_LIMIT'
          value: '230'
        }
        {
          name: 'OD_BIND_HOST'
          value: '0.0.0.0'
        }
        {
          name: 'OD_PORT'
          value: '${containerPort}'
        }
        {
          name: 'OD_WEB_PORT'
          value: '${containerPort}'
        }
        {
          name: 'OD_DATA_DIR'
          value: dataDir
        }
        {
          name: 'OD_PUBLIC_BASE_URL'
          value: publicBaseUrl
        }
        {
          name: 'OD_ALLOWED_ORIGINS'
          value: allowedOrigins
        }
        {
          name: 'OD_API_TOKEN'
          value: apiToken
        }
        {
          name: 'NODE_ENV'
          value: 'production'
        }
        {
          name: 'NODE_OPTIONS'
          value: nodeOptions
        }
      ]
    }
  }
}

@description('Public HTTPS URL of the deployed app.')
output appUrl string = publicBaseUrl

@description('Health endpoint to poll after deployment.')
output healthUrl string = '${publicBaseUrl}/api/health'

@description('Generated web app name (includes the unique suffix).')
output webAppName string = webAppName

targetScope = 'resourceGroup'

@description('Azure region for the Open Design container group and storage account.')
param location string = resourceGroup().location

@description('Container group name.')
param containerGroupName string = 'open-design'

@description('DNS label for the Azure Container Instances upstream endpoint. Must be unique in the selected region.')
param dnsNameLabel string = toLower('open-design-${uniqueString(resourceGroup().id, location)}')

@description('Open Design container image.')
param image string = 'ghcr.io/nexu-io/od:latest'

@secure()
@description('Required Open Design API token. Generate with: openssl rand -hex 32')
param odApiToken string

@description('Comma-separated browser-visible origins allowed by the daemon. Set this to the authenticated reverse proxy origin, for example https://od.example.com.')
param allowedOrigins string = ''

@description('Node.js heap cap inside the container.')
param nodeOptions string = '--max-old-space-size=192'

@description('CPU cores requested by the container.')
@minValue(1)
param cpuCores int = 1

@description('Memory requested by the container in GiB.')
@minValue(1)
param memoryInGB int = 1

@description('Azure Files share quota in GiB for persistent Open Design data.')
@minValue(1)
@maxValue(5120)
param fileShareQuotaGB int = 10

var storageAccountName = take(toLower('od${uniqueString(resourceGroup().id, location)}'), 24)
var fileShareName = 'opendesigndata'
var appPort = 7456

resource storageAccount 'Microsoft.Storage/storageAccounts@2023-05-01' = {
  name: storageAccountName
  location: location
  sku: {
    name: 'Standard_LRS'
  }
  kind: 'StorageV2'
  properties: {
    allowBlobPublicAccess: false
    minimumTlsVersion: 'TLS1_2'
    supportsHttpsTrafficOnly: true
  }
}

resource fileService 'Microsoft.Storage/storageAccounts/fileServices@2023-05-01' = {
  parent: storageAccount
  name: 'default'
}

resource dataShare 'Microsoft.Storage/storageAccounts/fileServices/shares@2023-05-01' = {
  parent: fileService
  name: fileShareName
  properties: {
    accessTier: 'TransactionOptimized'
    shareQuota: fileShareQuotaGB
  }
}

resource containerGroup 'Microsoft.ContainerInstance/containerGroups@2023-05-01' = {
  name: containerGroupName
  location: location
  properties: {
    osType: 'Linux'
    restartPolicy: 'Always'
    sku: 'Standard'
    ipAddress: {
      type: 'Public'
      dnsNameLabel: dnsNameLabel
      ports: [
        {
          protocol: 'TCP'
          port: appPort
        }
      ]
    }
    containers: [
      {
        name: 'open-design'
        properties: {
          image: image
          ports: [
            {
              protocol: 'TCP'
              port: appPort
            }
          ]
          environmentVariables: [
            {
              name: 'NODE_ENV'
              value: 'production'
            }
            {
              name: 'NODE_OPTIONS'
              value: nodeOptions
            }
            {
              name: 'OD_BIND_HOST'
              value: '0.0.0.0'
            }
            {
              name: 'OD_PORT'
              value: string(appPort)
            }
            {
              name: 'OD_WEB_PORT'
              value: string(appPort)
            }
            {
              name: 'OD_DATA_DIR'
              value: '/app/.od'
            }
            {
              name: 'OD_ALLOWED_ORIGINS'
              value: allowedOrigins
            }
            {
              name: 'OD_API_TOKEN'
              secureValue: odApiToken
            }
          ]
          resources: {
            requests: {
              cpu: cpuCores
              memoryInGB: memoryInGB
            }
          }
          volumeMounts: [
            {
              name: 'open-design-data'
              mountPath: '/app/.od'
              readOnly: false
            }
          ]
          livenessProbe: {
            httpGet: {
              path: '/api/health'
              port: appPort
              scheme: 'http'
            }
            initialDelaySeconds: 30
            periodSeconds: 30
            failureThreshold: 3
            timeoutSeconds: 5
          }
        }
      }
    ]
    volumes: [
      {
        name: 'open-design-data'
        azureFile: {
          shareName: dataShare.name
          storageAccountName: storageAccount.name
          storageAccountKey: listKeys(storageAccount.id, storageAccount.apiVersion).keys[0].value
          readOnly: false
        }
      }
    ]
  }
}

output daemonFqdn string = containerGroup.properties.ipAddress.fqdn
output proxyUpstreamUrl string = 'http://${containerGroup.properties.ipAddress.fqdn}:${appPort}'
output storageAccountName string = storageAccount.name
output fileShareName string = dataShare.name

import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { execFile } from 'node:child_process';
import { test } from 'node:test';
import assert from 'node:assert/strict';

// Guards the Azure Bicep templates against drifting from the Open Design
// runtime contract. Source-level checks run without the Azure CLI; the extra
// `bicep build` pass runs only when the bicep binary is on PATH.

const repoRoot = join(import.meta.dirname, '../..');
const azureDir = join(repoRoot, 'deploy/azure');
const appServicePath = join(azureDir, 'app-service.bicep');
const aciPath = join(azureDir, 'aci.bicep');

// Must match deploy/docker-compose.yml and charts/open-design.
const CONTAINER_PORT = '7456';
const DATA_DIR = '/app/.od';
const HEALTH_PATH = '/api/health';

// Env vars the daemon reads (apps/daemon/src).
const REQUIRED_ENV = [
  'OD_BIND_HOST',
  'OD_PORT',
  'OD_WEB_PORT',
  'OD_DATA_DIR',
  'OD_PUBLIC_BASE_URL',
  'OD_ALLOWED_ORIGINS',
  'OD_API_TOKEN',
  'NODE_ENV',
  'NODE_OPTIONS',
];

async function read(path: string): Promise<string> {
  return readFile(path, 'utf8');
}

for (const [label, path] of [
  ['app-service.bicep', appServicePath],
  ['aci.bicep', aciPath],
] as const) {
  test(`${label}: pins the runtime port and data dir`, async () => {
    const src = await read(path);
    assert.match(src, new RegExp(`var containerPort = ${CONTAINER_PORT}\\b`), 'container port must be 7456');
    assert.match(src, new RegExp(`var dataDir = '${DATA_DIR}'`), 'data dir must be /app/.od');
  });

  test(`${label}: requires a secure API token of at least 32 chars`, async () => {
    const src = await read(path);
    assert.match(src, /@secure\(\)\s*\n\s*@minLength\(32\)\s*\n\s*@description\([^)]*\)\s*\nparam apiToken string/);
  });

  test(`${label}: wires every required daemon env var`, async () => {
    const src = await read(path);
    for (const name of REQUIRED_ENV) {
      assert.ok(src.includes(`'${name}'`), `${label} is missing env var ${name}`);
    }
  });

  test(`${label}: probes the health endpoint`, async () => {
    const src = await read(path);
    assert.ok(src.includes(HEALTH_PATH), `${label} must reference ${HEALTH_PATH}`);
  });

  test(`${label}: keeps SQLite off Azure Files (SMB breaks SQLite locking)`, async () => {
    const src = await read(path);
    // The data dir holds app.sqlite + its WAL files; an Azure Files (SMB) mount
    // corrupts SQLite. The data dir must stay on the container's local disk.
    assert.doesNotMatch(src, /azureFile|azureStorageAccounts/i, `${label} must not mount the data dir to Azure Files`);
    assert.doesNotMatch(src, /Microsoft\.Storage\/storageAccounts\/fileServices\/shares/, `${label} must not declare a SQLite data file share`);
  });

  test(`${label}: derives allowed origins from the public base URL`, async () => {
    const src = await read(path);
    assert.match(src, /var allowedOrigins = empty\(extraAllowedOrigins\)/);
  });
}

test('app-service.bicep: enforces HTTPS and a single SQLite writer', async () => {
  const src = await read(appServicePath);
  assert.match(src, /httpsOnly:\s*true/, 'App Service must be HTTPS-only');
  assert.match(src, /numberOfWorkers:\s*1/, 'App Service must run a single worker for SQLite');
  assert.match(src, /capacity:\s*1/, 'App Service plan must be pinned to one instance');
  assert.ok(src.includes("'WEBSITES_PORT'"), 'App Service must set WEBSITES_PORT so traffic reaches the container');
  // Forces the data dir onto the container's local disk (Azure Files breaks SQLite).
  assert.match(src, /'WEBSITES_ENABLE_APP_SERVICE_STORAGE'\s*\n\s*value:\s*'false'/, 'App Service must disable Azure Files-backed storage');
});

test('aci.bicep: passes the API token as a secure value and always restarts', async () => {
  const src = await read(aciPath);
  assert.match(src, /name:\s*'OD_API_TOKEN'\s*\n\s*secureValue:\s*apiToken/, 'ACI must pass OD_API_TOKEN as a secureValue');
  assert.match(src, /restartPolicy:\s*'Always'/, 'ACI container should restart on failure');
});

// Compile the templates when a bicep binary is on PATH; skipped otherwise.
function findBicep(): Promise<string | null> {
  return new Promise((resolve) => {
    execFile('bicep', ['--version'], { timeout: 10_000 }, (err) => resolve(err ? null : 'bicep'));
  });
}

const bicepBin = await findBicep();

for (const [label, path] of [
  ['app-service.bicep', appServicePath],
  ['aci.bicep', aciPath],
] as const) {
  test(`${label}: compiles with bicep build`, { skip: bicepBin ? false : 'bicep CLI not installed' }, async () => {
    await new Promise<void>((resolve, reject) => {
      execFile('bicep', ['build', path, '--stdout'], { timeout: 60_000 }, (err, _stdout, stderr) => {
        if (err) {
          reject(new Error(`bicep build failed for ${label}: ${stderr || err.message}`));
          return;
        }
        // bicep prints lint warnings to stderr; treat any as a failure.
        assert.equal(stderr.trim(), '', `bicep emitted warnings for ${label}: ${stderr}`);
        resolve();
      });
    });
  });
}

import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { test } from 'node:test';
import assert from 'node:assert/strict';

const execFileAsync = promisify(execFile);
const repoRoot = join(import.meta.dirname, '../..');
const installScript = join(repoRoot, 'deploy/scripts/install.sh');
const uninstallScript = join(repoRoot, 'deploy/scripts/uninstall.sh');
const updateScript = join(repoRoot, 'deploy/scripts/update.sh');

// Skip entire suite if Docker is not available
function isDockerAvailable(): Promise<boolean> {
  return new Promise((resolve) => {
    execFile('docker', ['info'], { timeout: 5000 }, (err) => resolve(!err));
  });
}

const dockerAvailable = await isDockerAvailable();

// Unique test identifier to isolate from real deployments
const TEST_ID = `od-test-${process.pid}`;

async function waitForHealth(port: number, timeoutMs = 30000): Promise<boolean> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    try {
      const resp = await fetch(`http://127.0.0.1:${port}/api/health`);
      if (resp.ok) return true;
    } catch {}
    await new Promise((r) => setTimeout(r, 1000));
  }
  return false;
}

interface TestContext {
  tmpDir: string;
  port: number;
  projectName: string;
  containerName: string;
  volumeName: string;
}

async function setupTestDir(port: number): Promise<TestContext> {
  const projectName = `${TEST_ID}-${port}`;
  const containerName = projectName;
  const volumeName = `${projectName}-data`;

  const tmpDir = await mkdtemp(join(tmpdir(), `${TEST_ID}-`));
  await execFileAsync('cp', ['-r', join(repoRoot, 'deploy/.'), tmpDir]);

  // Write a compose override that replaces the hardcoded names
  const override = {
    name: projectName,
    services: {
      'open-design': {
        container_name: containerName,
        volumes: [`${volumeName}:/app/.od`],
      },
    },
    volumes: {
      [volumeName]: {},
    },
  };
  await writeFile(
    join(tmpDir, 'docker-compose.override.yml'),
    JSON.stringify(override),
  );

  return { tmpDir, port, projectName, containerName, volumeName };
}

function testEnv(ctx: TestContext): Record<string, string> {
  return {
    ...process.env as Record<string, string>,
    COMPOSE_PROJECT_NAME: ctx.projectName,
  };
}

async function teardownTestDir(ctx: TestContext): Promise<void> {
  const script = join(ctx.tmpDir, 'scripts/uninstall.sh');
  const override = join(ctx.tmpDir, 'docker-compose.override.yml');

  // Run uninstall with the same override file so it targets the test container
  try {
    await readFile(override);
    await execFileAsync('bash', [script, '--non-interactive'], {
      timeout: 60_000,
      env: testEnv(ctx),
    });
  } catch {}

  // Force-remove the named volume as a safety net
  try {
    await execFileAsync('docker', ['volume', 'rm', '-f', ctx.volumeName], {
      timeout: 10_000,
    });
  } catch {}

  if (ctx.tmpDir) await rm(ctx.tmpDir, { recursive: true, force: true });
}

// ---------------------------------------------------------------------------
// help flag tests — do not require Docker
// ---------------------------------------------------------------------------
test('install.sh --help exits 0', async () => {
  const { stdout } = await execFileAsync('bash', [installScript, '--help']);
  assert.match(stdout, /Usage/);
  assert.match(stdout, /--non-interactive/);
  assert.match(stdout, /--port/);
});

test('uninstall.sh --help exits 0', async () => {
  const { stdout } = await execFileAsync('bash', [uninstallScript, '--help']);
  assert.match(stdout, /Usage/);
  assert.match(stdout, /--keep-data/);
});

test('update.sh --help exits 0', async () => {
  const { stdout } = await execFileAsync('bash', [updateScript, '--help']);
  assert.match(stdout, /Usage/);
  assert.match(stdout, /--image/);
});

// ---------------------------------------------------------------------------
// Docker integration tests — skipped when Docker is unavailable
// ---------------------------------------------------------------------------
test('install.sh --non-interactive creates .env and starts container', { skip: !dockerAvailable ? 'Docker not available' : false }, async () => {
  const ctx = await setupTestDir(17456);
  try {
    const script = join(ctx.tmpDir, 'scripts/install.sh');
    await execFileAsync('bash', [
      script,
      '--non-interactive',
      `--port=${ctx.port}`,
      '--no-systemd',
    ], {
      timeout: 120_000,
      env: testEnv(ctx),
    });

    // .env should contain the port
    const envContent = await readFile(join(ctx.tmpDir, '.env'), 'utf8');
    assert.match(envContent, new RegExp(`OPEN_DESIGN_PORT=${ctx.port}`));

    // Container should be healthy
    const healthy = await waitForHealth(ctx.port, 60_000);
    assert.ok(healthy, 'daemon did not become healthy within 60s');
  } finally {
    await teardownTestDir(ctx);
  }
});

test('update.sh restarts service and remains healthy', { skip: !dockerAvailable ? 'Docker not available' : false }, async () => {
  const ctx = await setupTestDir(17457);
  try {
    const installRun = join(ctx.tmpDir, 'scripts/install.sh');
    await execFileAsync('bash', [
      installRun,
      '--non-interactive',
      `--port=${ctx.port}`,
      '--no-systemd',
    ], {
      timeout: 120_000,
      env: testEnv(ctx),
    });

    await waitForHealth(ctx.port, 30_000);

    // Update
    await execFileAsync('bash', [
      join(ctx.tmpDir, 'scripts/update.sh'),
    ], {
      timeout: 120_000,
      cwd: ctx.tmpDir,
      env: testEnv(ctx),
    });

    const healthy = await waitForHealth(ctx.port, 30_000);
    assert.ok(healthy, 'daemon not healthy after update');
  } finally {
    await teardownTestDir(ctx);
  }
});

test('uninstall.sh removes containers and .env', { skip: !dockerAvailable ? 'Docker not available' : false }, async () => {
  const ctx = await setupTestDir(17458);
  try {
    const installRun = join(ctx.tmpDir, 'scripts/install.sh');
    await execFileAsync('bash', [
      installRun,
      '--non-interactive',
      `--port=${ctx.port}`,
      '--no-systemd',
    ], {
      timeout: 120_000,
      env: testEnv(ctx),
    });

    // Uninstall
    await execFileAsync('bash', [
      join(ctx.tmpDir, 'scripts/uninstall.sh'),
      '--non-interactive',
    ], {
      timeout: 60_000,
      env: testEnv(ctx),
    });

    // .env should be gone
    const envGone = await readFile(join(ctx.tmpDir, '.env'), 'utf8').catch(() => null);
    assert.equal(envGone, null, '.env should have been removed');

    // Container should not be running
    const { stdout: containers } = await execFileAsync('docker', ['ps', '--format', '{{.Names}}']);
    assert.ok(!containers.includes(ctx.containerName), 'container should not be running after uninstall');
  } finally {
    await teardownTestDir(ctx);
  }
});

import { mkdir, mkdtemp, readFile, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { spawn } from "node:child_process";
import { test } from "node:test";
import assert from "node:assert/strict";

const repoRoot = path.resolve(import.meta.dirname, "../..");
const scriptPath = path.join(repoRoot, "deploy/scripts/prepare-colima-build-swap.sh");

type FakeHost = {
  os: string;
  arch: string;
};

type VmState = {
  memTotalKiB?: number;
  swapTotalKiB?: number;
  fallocateFails?: boolean;
  activeSwapFiles?: string[];
};

type RunOptions = {
  args?: string[];
  env?: Record<string, string>;
  host?: FakeHost;
  vm?: VmState;
};

function shellQuote(value: string): string {
  return `'${value.replaceAll("'", "'\\''")}'`;
}

async function runScript({
  args = ["status"],
  env = {},
  host = { os: "Darwin", arch: "arm64" },
  vm = {},
}: RunOptions = {}) {
  const tempDir = await mkdtemp(path.join(tmpdir(), "prepare-colima-build-swap-"));
  const binDir = path.join(tempDir, "bin");
  const remoteBinDir = path.join(tempDir, "remote-bin");
  await mkdir(binDir);
  await mkdir(remoteBinDir);

  const statePath = path.join(tempDir, "state.env");
  const commandLogPath = path.join(tempDir, "commands.log");
  await writeFile(
    statePath,
    [
      `MEM_TOTAL_KIB=${vm.memTotalKiB ?? 2097152}`,
      `SWAP_TOTAL_KIB=${vm.swapTotalKiB ?? 0}`,
      `FALLOCATE_FAILS=${vm.fallocateFails ? "1" : "0"}`,
      `ACTIVE_SWAP=${(vm.activeSwapFiles ?? []).join(":")}`,
      "DD_COUNT=",
      "FALLOCATE_SIZE=",
      "MKS_SWAP=",
      "SWAPON_TARGET=",
      "SWAPOFF_TARGETS=",
      "RM_TARGETS=",
    ].join("\n"),
  );

  await writeFile(
    path.join(binDir, "uname"),
    [
      "#!/usr/bin/env bash",
      "case \"$1\" in",
      `  -s) printf '%s\\n' ${shellQuote(host.os)} ;;`,
      `  -m) printf '%s\\n' ${shellQuote(host.arch)} ;;`,
      "  *) exit 2 ;;",
      "esac",
    ].join("\n"),
    { mode: 0o755 },
  );

  await writeFile(
    path.join(remoteBinDir, "awk"),
    [
      "#!/usr/bin/env bash",
      "set -euo pipefail",
      `source ${shellQuote(statePath)}`,
      "query=\"$*\"",
      "case \"$query\" in",
      "  *MemTotal*SwapTotal*)",
      "    printf 'MemTotal:       %s kB\\n' \"$MEM_TOTAL_KIB\"",
      "    printf 'SwapTotal:      %s kB\\n' \"$SWAP_TOTAL_KIB\"",
      "    ;;",
      "  *MemTotal*) printf '%s\\n' \"$MEM_TOTAL_KIB\" ;;",
      "  *SwapTotal*) printf '%s\\n' \"$SWAP_TOTAL_KIB\" ;;",
      "  *) exit 2 ;;",
      "esac",
    ].join("\n"),
    { mode: 0o755 },
  );

  await writeFile(
    path.join(remoteBinDir, "swapon"),
    [
      "#!/usr/bin/env bash",
      "set -euo pipefail",
      `source ${shellQuote(statePath)}`,
      "case \"${1:-}\" in",
      "  --show|--show=NAME)",
      "    old_ifs=\"$IFS\"",
      "    IFS=:",
      "    for item in $ACTIVE_SWAP; do",
      "      [ -n \"$item\" ] && printf '%s\\n' \"$item\"",
      "    done",
      "    IFS=\"$old_ifs\"",
      "    ;;",
      "  *)",
      "    printf 'unexpected swapon args: %s\\n' \"$*\" >&2",
      "    exit 2",
      "    ;;",
      "esac",
    ].join("\n"),
    { mode: 0o755 },
  );

  await writeFile(
    path.join(remoteBinDir, "sudo"),
    [
      "#!/usr/bin/env bash",
      "set -euo pipefail",
      `state=${shellQuote(statePath)}`,
      "set_state() {",
      "  key=\"$1\"",
      "  value=\"$2\"",
      "  tmp=\"$state.tmp\"",
      "  /usr/bin/awk -F= -v key=\"$key\" -v value=\"$value\" 'BEGIN { done=0 } $1 == key { print key \"=\" value; done=1; next } { print } END { if (!done) print key \"=\" value }' \"$state\" > \"$tmp\"",
      "  mv \"$tmp\" \"$state\"",
      "}",
      "append_state() {",
      "  key=\"$1\"",
      "  value=\"$2\"",
      "  current=\"$(/usr/bin/awk -F= -v key=\"$key\" '$1 == key { print substr($0, length(key) + 2); exit }' \"$state\")\"",
      "  if [ -n \"$current\" ]; then",
      "    set_state \"$key\" \"$current:$value\"",
      "  else",
      "    set_state \"$key\" \"$value\"",
      "  fi",
      "}",
      "source \"$state\"",
      "case \"$1\" in",
      "  fallocate)",
      "    if [ \"$FALLOCATE_FAILS\" = 1 ]; then",
      "      exit 1",
      "    fi",
      "    set_state FALLOCATE_SIZE \"$3\"",
      "    ;;",
      "  dd)",
      "    count=\"\"",
      "    for arg in \"$@\"; do",
      "      case \"$arg\" in",
      "        count=*) count=\"${arg#count=}\" ;;",
      "      esac",
      "    done",
      "    set_state DD_COUNT \"$count\"",
      "    ;;",
      "  chmod)",
      "    ;;",
      "  mkswap)",
      "    set_state MKS_SWAP \"$2\"",
      "    ;;",
      "  swapon)",
      "    set_state SWAPON_TARGET \"$2\"",
      "    set_state ACTIVE_SWAP \"$2\"",
      "    set_state SWAP_TOTAL_KIB 1",
      "    ;;",
      "  swapoff)",
      "    append_state SWAPOFF_TARGETS \"$2\"",
      "    set_state ACTIVE_SWAP \"\"",
      "    set_state SWAP_TOTAL_KIB 0",
      "    ;;",
      "  rm)",
      "    shift",
      "    [ \"${1:-}\" = -f ] && shift",
      "    for target in \"$@\"; do",
      "      append_state RM_TARGETS \"$target\"",
      "    done",
      "    ;;",
      "  *)",
      "    printf 'unexpected sudo command: %s\\n' \"$*\" >&2",
      "    exit 2",
      "    ;;",
      "esac",
    ].join("\n"),
    { mode: 0o755 },
  );

  await writeFile(
    path.join(binDir, "colima"),
    [
      "#!/usr/bin/env bash",
      "set -euo pipefail",
      `log=${shellQuote(commandLogPath)}`,
      `remote_bin=${shellQuote(remoteBinDir)}`,
      "printf '%s\\n' \"$*\" >> \"$log\"",
      "if [ \"$1\" = status ]; then",
      "  exit 0",
      "fi",
      "if [ \"$1\" != ssh ]; then",
      "  exit 2",
      "fi",
      "shift",
      "if [ \"${1:-}\" = -- ]; then",
      "  shift",
      "fi",
      "case \"$1\" in",
      "  awk)",
      "    PATH=\"$remote_bin:$PATH\" \"$@\"",
      "    ;;",
      "  sh)",
      "    shift",
      "    [ \"$1\" = -lc ] || exit 2",
      "    shift",
      "    script=\"$1\"",
      "    shift",
      "    env PATH=\"$remote_bin:$PATH\" bash -c \"$script\" \"$@\"",
      "    ;;",
      "  *)",
      "    exit 2",
      "    ;;",
      "esac",
    ].join("\n"),
    { mode: 0o755 },
  );

  const processResult = await new Promise<{ code: number | null; stderr: string }>((resolve, reject) => {
    const child = spawn("bash", [scriptPath, ...args], {
      env: {
        ...process.env,
        ...env,
        COLIMA_BIN: path.join(binDir, "colima"),
        PATH: `${binDir}${path.delimiter}${process.env.PATH ?? ""}`,
      },
      stdio: ["ignore", "ignore", "pipe"],
    });

    let stderr = "";
    child.stderr.setEncoding("utf8");
    child.stderr.on("data", (chunk) => {
      stderr += chunk;
    });
    child.on("error", reject);
    child.on("close", (code) => {
      resolve({ code, stderr });
    });
  });

  let colimaLog = "";
  try {
    colimaLog = await readFile(commandLogPath, "utf8");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
  }

  const state = Object.fromEntries(
    (await readFile(statePath, "utf8"))
      .trim()
      .split("\n")
      .map((line) => {
        const [key, ...value] = line.split("=");
        return [key, value.join("=")];
      }),
  );

  return { ...processResult, colimaLog, state };
}

test("prepare-colima-build-swap refuses Linux hosts before checking Colima", async () => {
  const result = await runScript({ args: ["status"], host: { os: "Linux", arch: "x86_64" } });

  assert.equal(result.code, 1);
  assert.match(result.stderr, /requires Apple Silicon macOS/);
  assert.equal(result.colimaLog, "");
});

test("prepare-colima-build-swap refuses Intel macOS hosts before checking Colima", async () => {
  const result = await runScript({ args: ["status"], host: { os: "Darwin", arch: "x86_64" } });

  assert.equal(result.code, 1);
  assert.match(result.stderr, /requires Apple Silicon macOS/);
  assert.equal(result.colimaLog, "");
});

test("prepare-colima-build-swap allows Apple Silicon macOS hosts to check Colima", async () => {
  const result = await runScript({ args: ["status"] });

  assert.equal(result.code, 0);
  assert.match(result.colimaLog, /^status\nssh -- sh -lc/m);
});

test("ensure creates and enables swap for low-memory Colima without swap", async () => {
  const result = await runScript({ args: ["ensure"] });

  assert.equal(result.code, 0);
  assert.equal(result.state.FALLOCATE_SIZE, "4G");
  assert.equal(result.state.MKS_SWAP, "/swapfile-colima-build");
  assert.equal(result.state.SWAPON_TARGET, "/swapfile-colima-build");
});

test("ensure uses the configured swap size when dd fallback is needed", async () => {
  const result = await runScript({
    args: ["ensure"],
    env: { COLIMA_BUILD_SWAP_SIZE: "6G" },
    vm: { fallocateFails: true },
  });

  assert.equal(result.code, 0);
  assert.equal(result.state.DD_COUNT, "6144");
  assert.equal(result.state.SWAPON_TARGET, "/swapfile-colima-build");
});

test("ensure is a no-op when Colima already has swap", async () => {
  const result = await runScript({ args: ["ensure"], vm: { swapTotalKiB: 1048576 } });

  assert.equal(result.code, 0);
  assert.equal(result.state.FALLOCATE_SIZE, "");
  assert.equal(result.state.SWAPON_TARGET, "");
});

test("ensure is a no-op when Colima memory is above the threshold", async () => {
  const result = await runScript({ args: ["ensure"], vm: { memTotalKiB: 8388608 } });

  assert.equal(result.code, 0);
  assert.equal(result.state.FALLOCATE_SIZE, "");
  assert.equal(result.state.SWAPON_TARGET, "");
});

test("cleanup removes the default and legacy swap paths", async () => {
  const result = await runScript({
    args: ["cleanup"],
    vm: { activeSwapFiles: ["/swapfile-colima-build"], swapTotalKiB: 1048576 },
  });

  assert.equal(result.code, 0);
  assert.equal(result.state.SWAPOFF_TARGETS, "/swapfile-colima-build");
  assert.equal(result.state.RM_TARGETS, "/swapfile-colima-build:/swapfile-open-design-build");
});

test("cleanup refuses custom swap paths unless force is enabled", async () => {
  const result = await runScript({
    args: ["cleanup"],
    env: { COLIMA_BUILD_SWAPFILE: "/custom-swapfile" },
    vm: { activeSwapFiles: ["/custom-swapfile"], swapTotalKiB: 1048576 },
  });

  assert.equal(result.code, 1);
  assert.match(result.stderr, /refusing to cleanup custom swap path/);
  assert.equal(result.state.RM_TARGETS, "");
});

test("cleanup removes custom swap paths when force is enabled", async () => {
  const result = await runScript({
    args: ["cleanup"],
    env: { COLIMA_BUILD_SWAPFILE: "/custom-swapfile", COLIMA_BUILD_SWAP_CLEANUP_FORCE: "1" },
    vm: { activeSwapFiles: ["/custom-swapfile"], swapTotalKiB: 1048576 },
  });

  assert.equal(result.code, 0);
  assert.equal(result.state.SWAPOFF_TARGETS, "/custom-swapfile");
  assert.equal(result.state.RM_TARGETS, "/custom-swapfile:/swapfile-open-design-build");
});

